"""
    compute total number of edges for a undirected graph
    :param ugraph:
    :return:
    """
def num_edges(ugraph: Any) -> object {
    total_edges = 0;
    for edges in ugraph.values() {
        total_edges += len(edges);
    }
    return (total_edges / 2);
}

