""" Escape s for use as a Javascript String """
def jsEscapeString(s: Any) -> object {
    return s.replace('\\', '\\\\').replace('\r', '\\r').replace('\n', '\\n').replace(
        '"', '\\"'
    ).replace(
        "'", "\\'"
    ).replace(
        "&", '\\x26'
    ).replace(
        "<", '\\x3C'
    ).replace(
        ">", '\\x3E'
    );
}

"""Check for 'assertRaises(Exception'.

    nova HACKING guide recommends not using assertRaises(Exception...):
    Do not use overly broad Exception type
    N202
    """
def nova_except_format_assert(logical_line: Any) -> object {
    if logical_line.startswith("self.assertRaises(Exception") {
        return (1, "NOVA N202: assertRaises Exception too broad");
    }
}

